"""Token bucket rate limiter."""


class TokenBucket:
    def __init__(self, capacity, refill_per_sec):
        self.capacity = capacity
        self.refill_per_sec = refill_per_sec
        self.tokens = capacity
        self.last = 0.0

    def allow(self, now):
        if self.tokens >= 1:
            self.tokens -= 1
            return True
        return False

